from django.utils.text import slugify


RESERVED_PREVIEW_SLUGS = {
    'www', 'admin', 'ops', 'portal', 'api', 'auth', 'sso',
    'mail', 'webmail', 'docs', 'status', 'cdn', 'static', 'app',
}


def populate_preview_slugs(apps, schema_editor):
    School = apps.get_model('tenants', 'School')
    used_slugs = set(
        School.objects.exclude(preview_slug='').values_list('preview_slug', flat=True)
    )
    for school in School.objects.all().order_by('created_at', 'id'):
        if school.preview_slug:
            continue
        base_source = (school.domain.split('.')[0] if school.domain else school.name) or 'escola'
        base = slugify(base_source)[:55].strip('-') or 'escola'
        if base in RESERVED_PREVIEW_SLUGS:
            base = f'escola-{base}'[:55]
        candidate = base
        counter = 2
        while candidate in used_slugs:
            suffix = f'-{counter}'
            candidate = f'{base[:63 - len(suffix)]}{suffix}'
            counter += 1
        used_slugs.add(candidate)
        school.preview_slug = candidate
        school.save(update_fields=['preview_slug'])


